-- ============================================================
-- 生产初始化数据：Java 后端开发方向 + 面试题库
-- 生成时间：2026-11-12
-- 来源：开发库 yszx（已合并 PDF 拆标题、补齐空答案）
-- 数据量：Java 方向 744 题，AI 方向 16 题，主题 20 个
-- 说明：
--   1. schema.sql 仅初始化 8 个 AI 方向，本脚本补齐第 9 个方向与题库；
--   2. 仅当目标学科下没有题目时批量写入，可安全重复执行；
--   3. source_doc_name / source_seq 保留原始文档与题号，便于追溯。
-- ============================================================

START TRANSACTION;

-- 1. Java 后端开发学科（第 9 个方向）
SELECT 'Java后端开发', '☕', 'Java 基础、集合、并发、JVM、框架与中间件等后端面试知识。', '#8A5A2B', 9
ON DUPLICATE KEY UPDATE
  `delete_flag` = 0,
  `icon` = VALUES(`icon`),
  `description` = VALUES(`description`),
  `theme_color` = VALUES(`theme_color`),
  `sort_order` = VALUES(`sort_order`);

SET @java_subject_id = (SELECT `id` FROM `subject` WHERE `name` = 'Java后端开发' AND `delete_flag` = 0 ORDER BY `id` LIMIT 1);
SET @ai_subject_id = (SELECT `id` FROM `subject` WHERE `name` = 'AI应用与智能体开发' AND `delete_flag` = 0 ORDER BY `id` LIMIT 1);

-- 2. 面试主题词表
SELECT NULL, t.`name`, t.`sort_order` FROM (
  SELECT '消息中间件' AS `name`, 1 AS `sort_order`
  UNION ALL SELECT 'MySQL' AS `name`, 2 AS `sort_order`
  UNION ALL SELECT 'Redis' AS `name`, 3 AS `sort_order`
  UNION ALL SELECT '微服务' AS `name`, 4 AS `sort_order`
  UNION ALL SELECT 'SSM' AS `name`, 5 AS `sort_order`
  UNION ALL SELECT 'Java集合' AS `name`, 6 AS `sort_order`
  UNION ALL SELECT 'JVM' AS `name`, 7 AS `sort_order`
  UNION ALL SELECT '多线程' AS `name`, 8 AS `sort_order`
  UNION ALL SELECT '设计模式' AS `name`, 9 AS `sort_order`
  UNION ALL SELECT '技术场景' AS `name`, 10 AS `sort_order`
  UNION ALL SELECT 'AI面试' AS `name`, 11 AS `sort_order`
  UNION ALL SELECT 'Python+AI' AS `name`, 12 AS `sort_order`
  UNION ALL SELECT 'Java面试' AS `name`, 13 AS `sort_order`
  UNION ALL SELECT 'Agent' AS `name`, 14 AS `sort_order`
  UNION ALL SELECT 'RAG' AS `name`, 15 AS `sort_order`
  UNION ALL SELECT '基础概念' AS `name`, 16 AS `sort_order`
  UNION ALL SELECT '多智能体' AS `name`, 17 AS `sort_order`
  UNION ALL SELECT '安全' AS `name`, 18 AS `sort_order`
  UNION ALL SELECT '工程实践' AS `name`, 19 AS `sort_order`
  UNION ALL SELECT '平台设计' AS `name`, 20 AS `sort_order`
) t
WHERE NOT EXISTS (SELECT 1 FROM `interview_topic` WHERE `subject_id` IS NULL AND `name` = t.`name` AND `delete_flag` = 0);

-- 3. Java 后端开发题库
CREATE TEMPORARY TABLE `tmp_java_questions` (
  `content` TEXT NOT NULL,
  `reference_answer` TEXT NULL,
  `topic` VARCHAR(50) NULL,
  `difficulty` TINYINT NOT NULL,
  `tags` VARCHAR(255) NULL,
  `source_type` TINYINT NOT NULL,
  `source_doc_name` VARCHAR(255) NULL,
  `source_seq` INT NULL,
  `status` TINYINT NOT NULL
);
SELECT @java_subject_id, `content`,`reference_answer`,`topic`,`difficulty`,`tags`,`source_type`,`source_doc_name`,`source_seq`,`status`
FROM `tmp_java_questions`
WHERE NOT EXISTS (SELECT 1 FROM `interview_question` WHERE `subject_id` = @java_subject_id AND `delete_flag` = 0);
DROP TEMPORARY TABLE `tmp_java_questions`;

-- 4. AI 应用与智能体开发题库
CREATE TEMPORARY TABLE `tmp_ai_questions` (
  `content` TEXT NOT NULL,
  `reference_answer` TEXT NULL,
  `topic` VARCHAR(50) NULL,
  `difficulty` TINYINT NOT NULL,
  `tags` VARCHAR(255) NULL,
  `source_type` TINYINT NOT NULL,
  `source_doc_name` VARCHAR(255) NULL,
  `source_seq` INT NULL,
  `status` TINYINT NOT NULL
);
SELECT @ai_subject_id, `content`,`reference_answer`,`topic`,`difficulty`,`tags`,`source_type`,`source_doc_name`,`source_seq`,`status`
FROM `tmp_ai_questions`
WHERE NOT EXISTS (SELECT 1 FROM `interview_question` WHERE `subject_id` = @ai_subject_id AND `delete_flag` = 0);
DROP TEMPORARY TABLE `tmp_ai_questions`;

COMMIT;
