INSERT INTO `tmp_ai_questions` (`content`,`reference_answer`,`topic`,`difficulty`,`tags`,`source_type`,`source_doc_name`,`source_seq`,`status`) VALUES
('RAG 的完整链路是什么？如何评估检索质量？', '完整链路：文档切分与向量化、写入向量库、查询改写、召回与重排、上下文拼接、生成并给出引用。检索质量可从召回率、命中率、MRR/NDCG、上下文相关性、答案忠实度评估，并结合离线评测集与线上反馈。', 'RAG', 2, 'RAG,检索,评测', 2, NULL, NULL, 1),
('Function Calling 或 Tool Use 的完整执行链路是什么？常见失败如何处理？', '模型选择工具并生成结构化参数，运行时校验参数，执行工具，把结果回填上下文，再决定下一步。失败处理包括参数校验、超时重试、幂等键、权限校验、错误信息回填、熔断与降级。', 'Agent', 2, 'Agent,工具调用,工程实践', 2, NULL, NULL, 1),
('多智能体系统如何做任务拆分与状态同步？', '按角色或能力拆分任务，使用编排器或图结构管理依赖关系；共享状态通过消息总线、黑板或持久化状态同步；同时设置终止条件、超时、冲突解决与人工接管机制。', '多智能体', 2, '多智能体,编排,状态同步', 2, NULL, NULL, 1),
('如何设计 Agent 的记忆机制？短期记忆与长期记忆如何取舍？', '短期记忆用会话上下文与窗口，长期记忆用向量库或结构化存储。写入时做重要性判断、去重与摘要，读取时做相关性检索；同时控制成本、隐私与过期策略。', 'Agent', 2, 'Agent,记忆,RAG', 2, NULL, NULL, 1),
('大模型输出不稳定时，如何设计结构化输出与校验？', '明确 JSON Schema，提供 few-shot 示例，优先使用 JSON mode 或 function calling；解析失败时重试或修复，逐字段校验并设置兜底默认值，关键结果保留人工复核。', '工程实践', 2, '结构化输出,校验,工程实践', 2, NULL, NULL, 1),
('如何控制 Agent 的循环与死循环？', '设置最大步数、超时与预算限制，加入状态去重和循环检测，明确终止条件，限制工具白名单，并在异常时降级或转人工接管。', 'Agent', 2, 'Agent,循环控制,稳定性', 2, NULL, NULL, 1),
('向量数据库选型需要考虑哪些因素？', '需要考虑数据规模、召回性能、元数据过滤能力、索引类型与更新成本、持久化与一致性、部署运维成本、生态集成与可观测性，并结合业务查询模式做压测。', 'RAG', 2, '向量数据库,RAG,选型', 2, NULL, NULL, 1),
('Prompt 注入攻击如何防护？', '隔离指令与数据，限制工具权限和白名单，过滤输入输出，避免把不可信内容直接拼进系统提示，对敏感操作增加二次确认与审计，并持续做红队测试。', '安全', 2, 'Prompt注入,安全,防护', 2, NULL, NULL, 1),
('如何评估一个 RAG 应用的效果？离线与在线指标分别看什么？', '离线关注召回率、NDCG、答案正确率、忠实度与引用准确率；在线关注任务完成率、用户反馈、采纳率、延迟、成本与异常率，并通过 A/B 测试验证改动。', 'RAG', 2, 'RAG,评测,指标', 2, NULL, NULL, 1),
('Agent 工具调用的幂等与超时应该如何处理？', '请求携带幂等键，服务端去重；为工具设置超时、重试与退避策略；工具本身尽量设计为幂等；失败时把错误回填给模型并触发降级或人工处理。', 'Agent', 2, 'Agent,幂等,超时', 2, NULL, NULL, 1),
('什么是大模型的上下文窗口？超出后怎么办？', '上下文窗口是模型一次能处理的最大 token 数。超出时可以截断、摘要、分段检索，或改用更长上下文的模型；同时要保留最关键的信息。', '基础概念', 1, '上下文,基础', 2, NULL, NULL, 1),
('什么是 Embedding？它在 RAG 中起什么作用？', 'Embedding 把文本映射为向量，用于语义相似度计算。RAG 中用 embedding 建立文档索引并把用户查询映射到向量空间，从而召回相关片段。', 'RAG', 1, 'Embedding,RAG,基础', 2, NULL, NULL, 1),
('Prompt 工程和微调有什么区别？', 'Prompt 工程通过指令和示例引导模型，成本低、迭代快；微调用训练数据更新模型参数，成本更高，但能改变模型行为和领域能力，适合稳定且高频的任务。', '基础概念', 1, 'Prompt,微调,基础', 2, NULL, NULL, 1),
('设计一个多租户 Agent 平台，如何做权限、隔离与成本控制？', '需要租户级数据隔离、RBAC/ABAC 权限、工具与模型访问控制、租户配额与预算、审计日志、资源池隔离、限流与成本告警，并保证跨租户不可见。', '平台设计', 3, '多租户,权限,成本', 2, NULL, NULL, 1),
('如何从零搭建大模型应用的可观测性与评测体系？', '采集请求、响应、工具调用、延迟与 token 成本；建立离线评测集与自动评分；线上做 A/B、告警、链路追踪与回归测试；把失败样本沉淀为新的评测用例。', '工程实践', 3, '可观测性,评测,工程实践', 2, NULL, NULL, 1),
('如何设计 Agent 的安全护栏与人工接管机制？', '输入输出过滤、工具白名单、敏感操作二次确认、风险分级、人工审核、审计日志与回滚；对高风险或低置信度操作自动转人工，并保留完整上下文。', '安全', 3, '安全,护栏,人工接管', 2, NULL, NULL, 1);
